private static async Task<string> StartMatch(ServiceContainer container, UIService ui)
{
    var deadline = new Deadline();
    var sb = Begin("StartMatch");
    var steps = new List<string>();

    string before = VisiblePages(ui);
    if (!IsPageOpen(ui, PageIds.Page_Room))
        throw new InvalidOperationException(
            "StartMatch 前置不满足：Page_Room 不可见。诊断：" + PageDiagnostics(ui));

    GameObject roomRoot = FindPageRoot("Page_Room");
    RoomFacts roomBefore = ReadRoomFacts(container, roomRoot);
    sb.AppendLine("room_before=" + roomBefore.Describe());
    if (roomBefore.HaveView && !roomBefore.IsOwner)
        throw new InvalidOperationException("StartMatch 前置不满足：当前玩家不是房主；" + roomBefore.Describe());

    SceneBaseline scenes = CaptureScenes();
    sb.AppendLine("scene_before=" + SceneDiagnostics(scenes));

    Button start = await WaitButtonReachable("Btn_StartMatch", "房间页房主开局钮", ui, deadline);
    steps.Add("expect=Btn_StartMatch 真实指针可点");
    ClickReport click = Click(start, "Room.Btn_StartMatch");
    steps.Add("click=" + click.Summary);

    int hudProbeTick = 0;
    await WaitUntil(() =>
    {
        if (IsPageOpen(ui, PageIds.Page_Room)) return false;
        if (IsPageOpen(ui, PageIds.Tmp_Loading)) return false;
        if (SceneAdvanced(scenes)) return true;
        hudProbeTick++;
        return hudProbeTick % 20 == 0 && BattleSurfaceByName();
    }, "Page_Room 关闭且 Loading 消失、战斗场景/HUD/SimView 开始", deadline,
        () => "开局后未进入战斗面；" + PageDiagnostics(ui) + ";" + SceneDiagnostics(scenes));

    steps.Add("assert=Page_Room 关闭");
    steps.Add("assert=Tmp_Loading 不在场");
    steps.Add("assert=战斗场景推进或 HUD/SimView 激活");

    sb.AppendLine("scene_after=" + SceneDiagnostics(scenes));
    sb.AppendLine("page_room_closed=" + (!IsPageOpen(ui, PageIds.Page_Room)).ToString().ToLowerInvariant());
    sb.AppendLine("loading_closed=" + (!IsPageOpen(ui, PageIds.Tmp_Loading)).ToString().ToLowerInvariant());
    sb.AppendLine("battle_surface=" + (SceneAdvanced(scenes) ? "scene_advanced" : "hud_or_simview"));

    string after = VisiblePages(ui);
    return Finish(sb, before, after, steps, click);
}

