private sealed class SceneBaseline
{
    public string Active;
    public List<string> Names;

    public bool Contains(string name) => Names != null && Names.Contains(name);

    public string Describe() => Names == null ? "(none)" : string.Join(",", Names.ToArray());
}

private static ServiceContainer ResolveContainer()

private static SceneBaseline CaptureScenes()
{
    var baseline = new SceneBaseline { Names = new List<string>() };
    Scene active = SceneManager.GetActiveScene();
    baseline.Active = active.name;
    for (int i = 0; i < SceneManager.sceneCount; i++)
    {
        Scene scene = SceneManager.GetSceneAt(i);
        if (scene.isLoaded) baseline.Names.Add(scene.name);
    }
    return baseline;
}

private static bool SceneAdvanced(SceneBaseline baseline)
{
    Scene active = SceneManager.GetActiveScene();
    if (active.isLoaded && !string.Equals(active.name, baseline.Active, StringComparison.Ordinal)) return true;
    for (int i = 0; i < SceneManager.sceneCount; i++)
    {
        Scene scene = SceneManager.GetSceneAt(i);
        if (scene.isLoaded && !baseline.Contains(scene.name)) return true;
    }
    return false;
}

private static bool BattleSurfaceByName()
{
    foreach (Transform transform in Object.FindObjectsOfType<Transform>(true))
    {
        if (transform == null || !transform.gameObject.activeInHierarchy) continue;
        string name = transform.gameObject.name;
        if (name.IndexOf("SimView", StringComparison.OrdinalIgnoreCase) >= 0) return true;
        if (name.StartsWith("Hud_", StringComparison.OrdinalIgnoreCase)) return true;
    }
    return false;
}

private static string SceneDiagnostics(SceneBaseline baseline)
{
    var names = new List<string>();
    for (int i = 0; i < SceneManager.sceneCount; i++)
    {
        Scene scene = SceneManager.GetSceneAt(i);
        if (scene.isLoaded) names.Add(scene.name);
    }
    return "active=" + SceneManager.GetActiveScene().name
           + ";loaded=" + string.Join(",", names.ToArray())
           + ";baseline=" + baseline.Describe();
}

